## Code Example
```javascript
// Pseudo: idempotent write to DynamoDB per tenant
const putEvent = async (tenantId, eventId, payload) => {
  await dynamodb.putItem({
    TableName: 'TenantEvents',
    Item: { tenantId: {S: tenantId}, eventId: {S: eventId}, payload: {S: JSON.stringify(payload)} },
    ConditionExpression: 'attribute_not_exists(eventId)'
  }).promise();
};
```

